      out.write("    <script>\r\n");
      out.write("        // Page loader\r\n");
      out.write("        window.addEventListener('load', function() {\r\n");
      out.write("            setTimeout(() => {\r\n");
      out.write("                document.getElementById('pageLoader').classList.add('hidden');\r\n");
