      out.write("\r\n");
      out.write("        // Scroll to top functionality\r\n");
      out.write("        document.getElementById('scrollTop').addEventListener('click', function() {\r\n");
      out.write("            window.scrollTo({\r\n");
      out.write("                top: 0,\r\n");
      out.write("                behavior: 'smooth'\r\n");
      out.write("            });\r\n");
      out.write("        });\r\n");
      out.write("\r\n");
      out.write("        // Enhanced button interactions with ripple effect\r\n");
      out.write("        document.addEventListener('DOMContentLoaded', function() {\r\n");
      out.write("            const buttons = document.querySelectorAll('.btn');\r\n");
      out.write("            buttons.forEach(button => {\r\n");
      out.write("                button.addEventListener('click', function(e) {\r\n");
      out.write("                    const ripple = document.createElement('span');\r\n");
      out.write("                    const rect = this.getBoundingClientRect();\r\n");
      out.write("                    const size = Math.max(rect.width, rect.height);\r\n");
      out.write("                    const x = e.clientX - rect.left - size / 2;\r\n");
      out.write("                    const y = e.clientY - rect.top - size / 2;\r\n");
      out.write("                    \r\n");
      out.write("                    ripple.style.cssText = `\r\n");
      out.write("                        position: absolute;\r\n");
      out.write("                        width: ${size}px;\r\n");
      out.write("                        height: ${size}px;\r\n");
      out.write("                        left: ${x}px;\r\n");
      out.write("                        top: ${y}px;\r\n");
      out.write("                        background: rgba(255, 255, 255, 0.3);\r\n");
      out.write("                        border-radius: 50%;\r\n");
      out.write("                        transform: scale(0);\r\n");
      out.write("                        animation: ripple 0.6s linear;\r\n");
      out.write("                        pointer-events: none;\r\n");
      out.write("                        z-index: 10;\r\n");
      out.write("                    `;\r\n");
      out.write("                    \r\n");
      out.write("                    this.appendChild(ripple);\r\n");
      out.write("                    \r\n");
      out.write("                    setTimeout(() => {\r\n");
      out.write("                        ripple.remove();\r\n");
      out.write("                    }, 600);\r\n");
      out.write("                });\r\n");
      out.write("            });\r\n");
      out.write("        });\r\n");
      out.write("\r\n");
      out.write("        // Intersection Observer for animations\r\n");
      out.write("        const observerOptions = {\r\n");
      out.write("            threshold: 0.1,\r\n");
      out.write("            rootMargin: '0px 0px -50px 0px'\r\n");
      out.write("        };\r\n");
      out.write("\r\n");
      out.write("        const observer = new IntersectionObserver(function(entries) {\r\n");
      out.write("            entries.forEach(entry => {\r\n");
      out.write("                if (entry.isIntersecting) {\r\n");
      out.write("                    entry.target.style.opacity = '1';\r\n");
      out.write("                    entry.target.style.transform = 'translateY(0)';\r\n");
      out.write("                }\r\n");
      out.write("            });\r\n");
      out.write("        }, observerOptions);\r\n");
      out.write("\r\n");
      out.write("        document.querySelectorAll('.section-card, .empty-state').forEach(el => {\r\n");
