      out.write("            el.style.transform = 'translateY(30px)';\r\n");
      out.write("            el.style.transition = 'all 0.6s ease-out';\r\n");
      out.write("            observer.observe(el);\r\n");
      out.write("        });\r\n");
      out.write("\r\n");
      out.write("        // Modal functions\r\n");
      out.write("        function openEditModal(id, email, firstName, lastName, address, telephone, isActive) {\r\n");
