      out.write("            document.getElementById('editAddress').value = address || '';\r\n");
      out.write("            document.getElementById('editTelephone').value = telephone || '';\r\n");
      out.write("            document.getElementById('editIsActive').checked = isActive;\r\n");
      out.write("            document.getElementById('editModalOverlay').style.display = 'block';\r\n");
      out.write("            document.body.style.overflow = 'hidden';\r\n");
